'use strict';
// Preserve each explorer's position across note selection, indexing and tab changes.
const explorerScroll=new Map(),interactionTree=renderTree;
renderTree=function(){const previous=$('#sidebar-content');if(previous?.dataset.scrollKey)explorerScroll.set(previous.dataset.scrollKey,previous.scrollTop);interactionTree();const current=$('#sidebar-content');if(current){const key=[workbench.source,workbench.project?.root||'',workbench.tab].join('\0');current.dataset.scrollKey=key;current.scrollTop=explorerScroll.get(key)||0;current.addEventListener('scroll',()=>explorerScroll.set(key,current.scrollTop),{passive:true})}};

const plainMarkdown=markdown;
function linkedMarkdown(body,source,project,interactive=false){
 const docs=project?discoveryDocs():vault.notes,refs=AmagoLinks.references(body).filter(r=>AmagoLinks.local(r.target)),replacements=[];let cursor=0,text='';
 for(const ref of refs){text+=body.slice(cursor,ref.start);const key='AMAGOREF'+replacements.length+'X'+Math.random().toString(36).slice(2)+'END';text+=key;cursor=ref.end;const target=AmagoLinks.resolve(docs,source,ref.target,{root:project?workbench.project?.root:'',aliases:d=>AmagoSearch.metadata(d.body).aliases}),image=project&&ref.embed&&target?.kind==='image';replacements.push([key,`<button class="wiki-link local-file-link ${image?'embedded-image':''} ${target?'':'unresolved-link'}" data-reference-embed="${!!ref.embed}" data-follow-reference="${esc(ref.target)}" data-reference-source="${esc(source?.path||source?.id||'')}" data-reference-space="${project?'project':'vault'}" ${image?`data-linked-image="${esc(target.path)}"`:''} title="${esc(target?.path||target?.title||ref.target)}">${image?'<span>Carregando imagem…</span>':esc(ref.label)}</button>`])}
 text+=body.slice(cursor);text=text.replace(/^ {0,3}\[[^\]\n]+\]:[^\n]*$/gm,'');let html=plainMarkdown(text,interactive);for(const [key,value] of replacements)html=html.replaceAll(key,value);return html;
}
markdown=function(body,interactive=true,source=note()){return linkedMarkdown(body,source,false,interactive)};
fileMarkdown=(body,source=workbench.file)=>linkedMarkdown(body,source,true);
window.addEventListener('click',async e=>{const el=e.target.closest('[data-follow-reference]');if(!el)return;e.preventDefault();e.stopImmediatePropagation();const project=el.dataset.referenceSpace==='project';if(project&&discovery.indexPromise)await discovery.indexPromise;const docs=project?discoveryDocs():vault.notes,source=docs.find(d=>(d.path||d.id)===el.dataset.referenceSource),target=AmagoLinks.resolve(docs,source,el.dataset.followReference,{root:project?workbench.project?.root:'',aliases:d=>AmagoSearch.metadata(d.body).aliases});if(!target){toast('Destino não encontrado. Use a pasta completa quando houver nomes repetidos.');return}if(project)await openProjectFile(target.path);else openNote(target.id);const fragment=AmagoLinks.targetParts(el.dataset.followReference).fragment;if(fragment)requestAnimationFrame(()=>{const query=AmagoSearch.normalize(fragment.replace(/-/g,' '));[...document.querySelectorAll('.markdown h1,.markdown h2,.markdown h3,.markdown h4')].find(h=>AmagoSearch.normalize(h.textContent)===query)?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})})},true);

const listConnectionPanel=connectionPanel;
connectionPanel=function(source,docs,project){const data=AmagoLinks.connections(docs,source,AmagoSearch.metadata,{root:project?workbench.project?.root:'',aliases:d=>AmagoSearch.metadata(d.body).aliases}),neighbors=[...new Map([...data.outgoing,...data.incoming].map(d=>[d.path||d.id,d])).values()],shown=neighbors.slice(0,8),center={x:130,y:100};const points=shown.map((d,i)=>({d,x:130+85*Math.cos(i*2*Math.PI/shown.length-Math.PI/2),y:100+65*Math.sin(i*2*Math.PI/shown.length-Math.PI/2)}));const svg=`<section class="local-network"><svg viewBox="0 0 260 200" aria-label="${neighbors.length} notas relacionadas"><g>${points.map(p=>`<line x1="130" y1="100" x2="${p.x}" y2="${p.y}"/>`).join('')}</g><circle cx="${center.x}" cy="${center.y}" r="10" style="fill:${AmagoSearch.metadata(source.body).color||'var(--accent)'}"><title>${esc(source.title||source.name)}</title></circle>${points.map(p=>`<g role="button" tabindex="0" ${project?`data-project-file="${esc(p.d.path)}"`:`data-note="${esc(p.d.id)}"`} aria-label="Abrir ${esc(p.d.title||p.d.name)}"><circle cx="${p.x}" cy="${p.y}" r="7" style="fill:${AmagoSearch.metadata(p.d.body).color||'var(--accent)'}"/><text x="${p.x}" y="${p.y+19}" text-anchor="middle">${esc((p.d.title||p.d.name).slice(0,13))}</text><title>${esc(p.d.path||p.d.title)}</title></g>`).join('')}</svg><button class="plain-button" data-local-atlas="${esc(source.path||source.id)}">${icon('graph')}Mapa desta nota · ${neighbors.length}</button>${neighbors.length>8?'<small>Prévia com 8 pontos. Abra o mapa para ver os demais.</small>':''}</section>`;return listConnectionPanel(source,docs,project).replace('</h3><section','</h3>'+svg+'<section')};
window.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('.local-network g[role="button"]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}},true);
window.addEventListener('dblclick',e=>{if(e.target.closest('.topbar')&&!e.target.closest('button,input,a,select'))window.amagoDesktop?.windowControl('maximize')});

// A single suggestion popup follows the active editor, including split columns.
let completion=null;
function closeCompletion(){if(completion){completion.editor.removeAttribute('aria-activedescendant');completion.editor.removeAttribute('aria-controls');completion.editor.removeAttribute('aria-expanded')}$('#editor-completion')?.remove();completion=null}
function editorDocument(editor){if(editor.matches('[data-pane-editor]'))return paneDocument(studio.panes[+editor.dataset.paneEditor]);return editor.id==='project-editor'?workbench.file:note()}
function positionCompletion(editor,popup){const mirror=document.createElement('div'),style=getComputedStyle(editor),rect=editor.getBoundingClientRect();for(const key of ['font','fontSize','fontFamily','fontWeight','lineHeight','letterSpacing','padding','border','boxSizing','tabSize','wordSpacing'])mirror.style[key]=style[key];Object.assign(mirror.style,{position:'fixed',visibility:'hidden',whiteSpace:'pre-wrap',overflowWrap:'break-word',width:editor.clientWidth+'px',left:'0',top:'0'});mirror.textContent=editor.value.slice(0,editor.selectionStart);const marker=document.createElement('span');marker.textContent='\u200b';mirror.append(marker);document.body.append(mirror);const x=rect.left+marker.offsetLeft-editor.scrollLeft,y=rect.top+marker.offsetTop-editor.scrollTop+(parseFloat(style.lineHeight)||22);mirror.remove();popup.style.left=Math.max(8,Math.min(innerWidth-popup.offsetWidth-8,x))+'px';popup.style.top=Math.max(8,Math.min(innerHeight-popup.offsetHeight-8,y))+'px'}
function updateCompletion(editor,force=false){if(!editor.matches('#editor,#project-editor,[data-pane-editor]')||editorDocument(editor)?.kind==='text')return closeCompletion();const token=AmagoCompletion.token(editor.value,editor.selectionStart,force||completion?.forced&&completion.editor===editor);if(!token||editor.selectionStart!==editor.selectionEnd)return closeCompletion();const items=completion?.editor===editor?completion.items:AmagoCompletion.candidates(discoveryDocs());const candidates=AmagoCompletion.suggest(items,token);if(!candidates.length)return closeCompletion();const forced=force||completion?.forced;closeCompletion();completion={editor,token,items,candidates,index:0,forced};const popup=document.createElement('div');popup.id='editor-completion';popup.className='editor-completion';popup.setAttribute('role','listbox');popup.setAttribute('aria-label','Sugestões de páginas, tags e menções');popup.innerHTML='<div class="completion-heading">CONECTAR IDEIAS <small>↑ ↓ · Enter · Esc</small></div>'+candidates.map((c,i)=>`<button role="option" id="completion-${i}" aria-selected="${i===0}" tabindex="-1" data-completion="${i}">${icon(c.kind==='page'?'note':c.kind==='tag'?'tag':'link')}<span><strong>${esc(c.kind==='tag'?'#'+c.label:c.kind==='mention'?'@'+c.label:c.label)}</strong><small>${esc(c.path|| (c.kind==='tag'?'Tag':'Menção'))}</small></span></button>`).join('');document.body.append(popup);editor.setAttribute('aria-autocomplete','list');editor.setAttribute('aria-controls',popup.id);editor.setAttribute('aria-expanded','true');editor.setAttribute('aria-activedescendant','completion-0');popup.onpointerdown=e=>{const button=e.target.closest('[data-completion]');if(button){e.preventDefault();acceptCompletion(+button.dataset.completion)}};positionCompletion(editor,popup)}
function acceptCompletion(index){if(!completion)return;const {editor,token,candidates}=completion,text=AmagoCompletion.insertion(candidates[index],token);closeCompletion();const top=editor.scrollTop;editor.focus({preventScroll:true});editor.setRangeText(text,token.start,token.end,'end');editor.dispatchEvent(new Event('input',{bubbles:true}));closeCompletion();editor.scrollTop=top}
window.addEventListener('input',e=>{if(!e.isComposing&&e.target.matches('#editor,#project-editor,[data-pane-editor]'))updateCompletion(e.target)},true);
window.addEventListener('keydown',e=>{if(e.isComposing)return;if((e.ctrlKey||e.metaKey)&&(e.code==='Space'||e.key===' ')&&e.target.matches('textarea')){e.preventDefault();e.stopImmediatePropagation();updateCompletion(e.target,true);return}if(!completion||e.target!==completion.editor)return;if(['Escape','ArrowUp','ArrowDown','Enter','Tab'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(e.key==='Escape')return closeCompletion();if(e.key==='Enter'||e.key==='Tab')return acceptCompletion(completion.index);completion.index=(completion.index+(e.key==='ArrowDown'?1:-1)+completion.candidates.length)%completion.candidates.length;document.querySelectorAll('[data-completion]').forEach((b,i)=>b.setAttribute('aria-selected',String(i===completion.index)));completion.editor.setAttribute('aria-activedescendant','completion-'+completion.index);$('#completion-'+completion.index)?.scrollIntoView({block:'nearest'})}else if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key))closeCompletion()},true);
window.addEventListener('pointerdown',e=>{if(completion&&!e.target.closest('#editor-completion')&&e.target!==completion.editor)closeCompletion()},true);
window.addEventListener('focusout',e=>{if(completion?.editor===e.target)closeCompletion()},true);
window.addEventListener('resize',closeCompletion);document.addEventListener('scroll',e=>{if(completion&&!e.target.closest?.('#editor-completion'))closeCompletion()},true);

function graphNeighborhood(edges,focus,depth){const set=new Set([focus]);for(let i=0;i<depth;i++){const before=new Set(set);for(const e of edges){if(before.has(e.a))set.add(e.b);if(before.has(e.b))set.add(e.a)}}return set}
function graphPosition(docs,index,layout){const d=docs[index],angle=index*Math.PI*2/Math.max(1,docs.length);if(layout==='circle')return {x:500+350*Math.cos(angle),y:290+230*Math.sin(angle)};if(layout==='folders'){const folder=d=>d.path?.split('/').slice(0,-1).join('/')||d.folder||'Raiz',groups=[...new Set(docs.map(folder))].sort(),group=groups.indexOf(folder(d)),members=docs.filter(item=>folder(item)===folder(d)),i=members.indexOf(d),a=i*2.399963,r=members.length===1?0:Math.min(90,15+Math.sqrt(i)*80/Math.sqrt(members.length)),columns=Math.ceil(Math.sqrt(groups.length)),rows=Math.ceil(groups.length/columns);return {x:(group%columns+.5)*1000/columns+Math.cos(a)*r,y:(Math.floor(group/columns)+.5)*550/rows+Math.sin(a)*r}}const a=index*2.399963,r=docs.length<2?0:Math.min(240,35+Math.sqrt(index)*240/Math.sqrt(docs.length));return {x:500+Math.cos(a)*r*1.5,y:290+Math.sin(a)*r}}
const fullGraphData=graphData;graphData=function(){const data=fullGraphData(discovery.localFocus?Infinity:500);if(!discovery.localFocus)return data;const visible=graphNeighborhood(data.edges,discovery.localFocus,graphPreferences().depth||1),docs=data.docs.filter(d=>visible.has(docId(d)));const shown=docs.slice(0,500),ids=new Set(shown.map(docId));return {...data,docs:shown,edges:data.edges.filter(e=>ids.has(e.a)&&ids.has(e.b)),total:docs.length}};
const baseUniverse=renderUniverse;renderUniverse=function(){baseUniverse();const prefs=graphPreferences();$('.universe-toolbar').insertAdjacentHTML('afterbegin',`<label>Organização <select id="atlas-layout" aria-label="Organização do mapa">${[['organic','Orgânica'],['circle','Circular'],['folders','Por pasta'],['flow','Fluxograma'],['columns','Colunas']].map(([id,label])=>`<option value="${id}" ${(prefs.layout||'organic')===id?'selected':''}>${label}</option>`).join('')}</select></label><label><input id="atlas-labels" type="checkbox" ${prefs.labels!==false?'checked':''}>Nomes</label><label>Vizinhança <select id="atlas-depth" aria-label="Profundidade das conexões">${[1,2,3].map(n=>`<option value="${n}" ${(prefs.depth||1)===n?'selected':''}>${n} nível${n>1?'s':''}</option>`).join('')}</select></label><button class="plain-button" id="atlas-focus">${discovery.localFocus?'Mostrar todo o mapa':'Focar nota selecionada'}</button>`);$('#universe-nodes').classList.toggle('hide-labels',prefs.labels===false);$('#atlas-layout').onchange=e=>{prefs.layout=e.target.value;prefs.positions={};graphPan={x:0,y:0,zoom:1};persist();renderUniverse()};$('#atlas-labels').onchange=e=>{prefs.labels=e.target.checked;persist();$('#universe-nodes').classList.toggle('hide-labels',!prefs.labels)};$('#atlas-depth').onchange=e=>{prefs.depth=+e.target.value;persist();renderUniverse()};$('#atlas-focus').onclick=()=>{if(discovery.localFocus)discovery.localFocus=null;else if(discovery.selected)discovery.localFocus=discovery.selected;else{toast('Selecione um ponto para explorar sua vizinhança.');return}renderUniverse()}};
window.addEventListener('click',e=>{const local=e.target.closest('[data-local-atlas]');if(local){e.preventDefault();e.stopImmediatePropagation();discovery.localFocus=local.dataset.localAtlas;discovery.selected=discovery.localFocus;discovery.graphQuery='';state.view='graph';render()}else if(e.target.closest('[data-open-universe],[data-view="graph"]'))discovery.localFocus=null},true);
